<section class="admin-page"><div class="admin-title-row"><div><p class="eyebrow">Hima</p><h1>{{ __('store.manage_orders') }}</h1></div></div>
    <div class="admin-form admin-form-grid"><label>{{ __('store.order_status') }}<select wire:model.live="statusFilter"><option value="">{{ __('store.all') }}</option>@foreach (['pending','confirmed','shipped','delivered','cancelled','return_requested'] as $status)<option value="{{ $status }}">{{ __('store.status_'.$status) }}</option>@endforeach</select></label><label>{{ __('store.payment_status') }}<select wire:model.live="paymentFilter"><option value="">{{ __('store.all') }}</option>@foreach (['unpaid','awaiting_review','paid','rejected'] as $status)<option value="{{ $status }}">{{ __('store.payment_status_'.$status) }}</option>@endforeach</select></label></div>
    <div class="admin-order-list">@forelse ($orders as $order)
        <article class="admin-order"><header><strong>{{ $order->number }}</strong><time>{{ $order->placed_at->format('Y-m-d H:i') }}</time><span>{{ $order->customer_name }} · <a href="https://wa.me/{{ ltrim($order->phone_e164, '+') }}" target="_blank" rel="noopener">{{ $order->phone_e164 }}</a></span><b>{{ number_format((float) $order->total, 0) }} {{ __('store.currency') }}</b></header>
            <p>{{ $order->governorate_name }} · {{ $order->address }} · {{ __('store.payment_'.$order->payment_method) }}</p>
            <div class="order-items">@foreach ($order->items as $item)<div><span>{{ $item->product_name_ar }} · {{ $item->color_name }} · {{ $item->size }} × {{ $item->quantity }}</span><b>{{ number_format((float) $item->line_total, 0) }}</b></div>@endforeach</div>
            <div class="admin-order-actions"><span>{{ __('store.status_'.$order->status) }} · {{ __('store.payment_status_'.$order->payment_status) }}</span>
                @if ($order->payment_status === 'awaiting_review')<a class="text-action" href="{{ route('admin.orders.proof', $order) }}" target="_blank" rel="noopener">{{ __('store.view_payment_proof') }}</a><button wire:click="reviewPayment({{ $order->id }}, 'paid')">{{ __('store.mark_paid') }}</button><button wire:click="reviewPayment({{ $order->id }}, 'rejected')">{{ __('store.reject_payment') }}</button>@endif
                @php($next = ['pending'=>['confirmed','cancelled'],'confirmed'=>['shipped','cancelled'],'shipped'=>['delivered']][$order->status] ?? [])
                @foreach ($next as $status)<button wire:click="changeStatus({{ $order->id }}, '{{ $status }}')">{{ __('store.status_'.$status) }}</button>@endforeach
            </div>
        </article>
    @empty<div class="table-empty">{{ __('store.no_orders') }}</div>@endforelse</div>{{ $orders->links() }}
    <section class="admin-return-list"><h2>{{ __('store.pending_returns') }}</h2>@forelse ($returns as $return)<article class="admin-order"><strong>{{ $return->order->number }} · {{ $return->user->name }} · {{ __('store.return_status_'.$return->status) }}</strong><p>{{ $return->reason }}</p>@if ($return->status === 'requested')<button wire:click="resolveReturn({{ $return->id }}, 'approved')">{{ __('store.approve_return') }}</button><button wire:click="resolveReturn({{ $return->id }}, 'rejected')">{{ __('store.reject_return') }}</button>@elseif ($return->status === 'approved')<button wire:click="resolveReturn({{ $return->id }}, 'received')">{{ __('store.mark_return_received') }}</button>@elseif ($return->status === 'received')<label>{{ __('store.refund_amount') }}<input type="number" min="0" step="0.01" wire:model="refundAmount"></label>@error('refundAmount')<small class="field-error">{{ $message }}</small>@enderror<button wire:click="resolveReturn({{ $return->id }}, 'refunded')">{{ __('store.mark_refunded') }}</button>@endif</article>@empty<p>{{ __('store.no_pending_returns') }}</p>@endforelse</section>
</section>
